shader-strata.source:
precision highp float;

uniform vec2 u_res;
uniform float u_time;
uniform float u_layers;
uniform float u_amp;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
uniform vec3 u_accent;
uniform float u_accentAmt;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p *= 2.03;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;

  // Deeper layers drift faster — parallax without per-band recursion.
  float drift = u_time * (0.012 + 0.05 * (1.0 - uv.y));
  float w = fbm(vec2(uv.x * 2.6 * aspect + drift, uv.y * 2.2 - u_time * 0.01));

  float yd = uv.y + (w - 0.5) * u_amp;
  float band = yd * u_layers;
  float idx = floor(band);
  float f = fract(band);

  // Per-band value jitter + a soft sediment shadow at each band's lower edge.
  float j = hash(vec2(idx, 7.0));
  float edge = smoothstep(0.0, 0.4, f) * (1.0 - 0.3 * smoothstep(0.8, 1.0, f));

  float depth = clamp(idx / u_layers, 0.0, 1.0);
  vec3 col = mix(u_c0, u_c1, smoothstep(0.0, 0.4, depth));
  col = mix(col, u_c2, smoothstep(0.35, 0.75, depth));
  col = mix(col, u_c3, smoothstep(0.7, 1.0, depth));
  col *= 0.84 + 0.16 * j;
  col *= 0.92 + 0.08 * edge;

  // The accent rises from the deep strata and thins toward the surface.
  float mask = (1.0 - uv.y);
  mask *= mask;
  col = mix(col, u_accent, clamp(u_accentAmt, 0.0, 1.0) * mask * 0.38);

  // A whisper of living grain, time-derived so it stays deterministic.
  col += (hash(gl_FragCoord.xy + floor(u_time * 9.0)) - 0.5) * 0.012;

  gl_FragColor = vec4(col, 1.0);
}

shader-weave.source:
precision highp float;

uniform vec2 u_res;
uniform float u_time;
uniform float u_scale;
uniform float u_warp;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
uniform vec3 u_accent;
uniform float u_accentAmt;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p *= 2.03;
    a *= 0.5;
  }
  return v;
}

// A thin ridge line at every integer of x — the profile of one thread.
float thread(float x, float sharp) {
  float f = fract(x);
  float d = min(f, 1.0 - f);
  return smoothstep(sharp, 0.0, d);
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  float aspect = u_res.x / u_res.y;

  // Domain warp — bend the weave so it reads hand-made, not a CSS grid. The
  // warp field drifts very slowly; the grid lattice itself stays put.
  vec2 q = uv + u_warp * vec2(
    fbm(uv * 3.0 + vec2(u_time * 0.03, 0.0)) - 0.5,
    fbm(uv * 3.0 + vec2(7.3, -u_time * 0.02)) - 0.5
  );

  float qx = q.x * u_scale * aspect;
  float qy = q.y * u_scale;

  float tw = thread(qx, 0.09); // warp (vertical threads)
  float tf = thread(qy, 0.09); // weft (horizontal threads)

  // Interlace: per cell, one direction sits over the other.
  float over = mod(floor(qx) + floor(qy), 2.0);
  float warpB = tw * (over < 0.5 ? 1.0 : 0.5);
  float weftB = tf * (over < 0.5 ? 0.5 : 1.0);
  float weave = max(warpB, weftB);

  // Sheen — light travelling across a still cloth (this is the only motion).
  float sheen = fbm(q * 1.7 + vec2(u_time * 0.05, u_time * 0.028));
  weave *= 0.3 + 0.95 * sheen;

  // Fabric ground: near-black, faintly breathing between the shadow stops.
  vec3 base = mix(u_c0, u_c1, smoothstep(0.15, 0.8, sheen));
  base = mix(base, u_c2, smoothstep(0.62, 1.0, sheen) * 0.5);

  // Threads sit a touch above the ground.
  vec3 col = mix(base, u_c3, clamp(weave, 0.0, 1.0) * 0.55);

  // The accent runs through the threads — a violet thread across the cloth.
  float amt = clamp(u_accentAmt, 0.0, 1.0);
  col = mix(col, u_accent, amt * (0.08 + 0.34 * weave));
  col += u_accent * amt * 0.015;

  // A whisper of living grain, time-derived so it stays deterministic.
  col += (hash(gl_FragCoord.xy + floor(u_time * 9.0)) - 0.5) * 0.012;

  gl_FragColor = vec4(col, 1.0);
}

shader-text-reveal.source:
#version 300 es
precision highp float;

uniform vec2 iResolution;
uniform float iTime;
uniform float uLightMode;
uniform vec3 uDarkBackground;
uniform vec3 uLightBackground;
out vec4 fragColor;

const float HUE = 0.663466752;
const float HUE_SPREAD = 0.314346701;
const float HUE_TRAVEL = 1.65112376;
const float CHROMA = 0.160295546;
const float LIGHTNESS = 0.537409723;
const float COLOUR_CYCLE = 0.124862425;
const float THETA = 2.12986207;
const float SHEAR = 0.968176901;
const float SHRINK = 0.955401778;
const float LAYERS = 72.0;
const float WARP_FREQ_X = 0.439311415;
const float WARP_FREQ_Y = 2.87923527;
const float WARP_AMP_X = 0.156202048;
const float WARP_AMP_Y = 0.0256033838;
const float ASPECT_X = 2.23183894;
const float ASPECT_Y = 0.15731883;
const float OFFSET_X = 0.375628948;
const float OFFSET_Y = -0.017801486;
const float TILT = 1.63293767;
const float ZOOM = 0.93135649;
const float CENTRE_X = -0.0956316143;
const float CENTRE_Y = -0.520057321;
const float GLOW_SIZE = 0.00201825937;
const float FALLOFF = 0.352821857;
const float VIGNETTE = 0.136085436;
const float FLOW_SPEED = 0.391012281;
const float FLOW_DIRECTION = 1.0;
const float BREATH_RATE = 0.382053256;
const float BREATH_AMOUNT = 0.0873704553;
const float PHASE = 56.3862724;
const float ECHO = 0.0;
const float ECHO_SHIFT = 0.178754866;
const float SOFTNESS = 0.00164903817;
const float LIGHT_SWING = 0.149726808;

const float TAU = 6.28318530718;

vec3 oklchToLinear(float L, float C, float h) {
  float a = C * cos(h), b = C * sin(h);
  float l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  float m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  float s_ = L - 0.0894841775 * a - 1.2914855480 * b;
  vec3 lms = vec3(l_, m_, s_);
  lms = lms * lms * lms;
  return mat3(4.0767416621, -1.2684380046, -0.0041960863,
              -3.3077115913, 2.6097574011, -0.7034186147,
              0.2309699292, -0.3413193965, 1.7076147010) * lms;
}

float blueNoise(vec2 p, float frame) {
  p += 5.588238 * mod(frame, 64.0);
  return fract(52.9829189 * fract(0.06711056 * p.x + 0.00583715 * p.y));
}

void main() {
  vec2 R = iResolution.xy;
  vec2 pos = (gl_FragCoord.xy - 0.5 * R) / R.y;
  float t = iTime * FLOW_SPEED * FLOW_DIRECTION + PHASE;
  float breath = (-sin(iTime * BREATH_RATE * 1.5) + sin(iTime * BREATH_RATE + 1.0)) * 0.25 + 0.5;

  vec2 u = (pos - vec2(CENTRE_X, CENTRE_Y)) * (ZOOM - breath * BREATH_AMOUNT);
  float ct = cos(TILT), st = sin(TILT);
  u = mat2(ct, st, -st, ct) * u;

  mat2 fold = mat2(cos(THETA), sin(THETA), -SHEAR, cos(THETA));

  float hue0 = HUE * TAU;
  float hue1 = hue0 + HUE_SPREAD * TAU;
  vec3 color = vec3(0.0);

  for (float i = 1.0; i <= 96.0; i += 1.0) {
    if (i > LAYERS) break;
    u.x += -sin(u.y * WARP_FREQ_X + t + i * 0.007) * WARP_AMP_X;
    u.y += -sin(u.x * WARP_FREQ_Y - t + i * 0.02) * WARP_AMP_Y;
    u = fold * u * SHRINK;

    vec2 q = u - vec2(OFFSET_X + breath * 0.1, OFFSET_Y);
    vec2 s = vec2(q.x * ASPECT_X, q.y * ASPECT_Y);
    float glow = GLOW_SIZE / (dot(s, s) + SOFTNESS);
#ifndef SKIP_ECHO
    vec2 e = vec2((q.x - ECHO_SHIFT) * ASPECT_X, s.y);
    glow += ECHO * GLOW_SIZE / (dot(e, e) + SOFTNESS);
#endif
    glow *= 0.25 + breath * 0.4;

    float r = length(u);
    float k = sin(i * COLOUR_CYCLE + t * 1.2 + r * HUE_TRAVEL) * 0.5 + 0.5;
    vec3 tint = clamp(oklchToLinear(LIGHTNESS + LIGHT_SWING * k, CHROMA * (0.75 + 0.35 * k), mix(hue0, hue1, k)), 0.0, 1.0);
    color += glow * tint * exp2(-r * FALLOFF);
  }

  vec3 x = max(color, 0.0);
  color = (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14);
  color = pow(clamp(color, 0.0, 1.0), vec3(0.85, 0.92, 0.98));

  float edge = smoothstep(0.5, 1.6, length(pos));
  color *= 1.0 - edge * VIGNETTE;

  vec3 dark = uDarkBackground + color * (1.0 - uDarkBackground);
  float strength = max(color.r, max(color.g, color.b));
  vec3 light = uLightBackground * (1.0 - strength) + color * 0.96;
  color = mix(dark, light, uLightMode);

  color += (blueNoise(gl_FragCoord.xy, floor(iTime * 24.0)) - 0.5) / 255.0;
  fragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
}

sustained-glitch.source:
#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform float u_intensity;
uniform float u_frequency;
uniform float u_slices;
uniform float u_seed;

in vec2 v_uv;
out vec4 outColor;

const float BLOCK_COLUMNS = 16.0;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

vec4 sampleSplit(vec2 uv, float split) {
  vec4 center = texture(u_scene, uv);
  float r = texture(u_scene, fract(vec2(uv.x + split, uv.y))).r;
  float b = texture(u_scene, fract(vec2(uv.x - split, uv.y))).b;
  return vec4(r, center.g, b, center.a);
}

void main() {
  float slotLength = max(30.0 / max(u_frequency, 0.1), 4.0);
  float slot = floor(u_frame / slotLength);
  float local = u_frame - slot * slotLength;

  float burstLength = 2.0 + floor(hash(vec2(slot, u_seed + 2.0)) * 4.0);
  float start =
    floor(hash(vec2(slot, u_seed + 1.0)) * max(slotLength - burstLength, 1.0));
  float fires = step(0.25, hash(vec2(slot, u_seed + 3.0)));

  float age = local - start;
  float live = fires * step(0.0, age) * step(age, burstLength - 1.0);
  float energy =
    max(u_intensity, 0.0) * live * (1.0 - age / burstLength);

  if (energy <= 0.0) {
    outColor = texture(u_scene, v_uv);
    return;
  }

  float clock = mod(u_frame, 512.0) + u_seed;
  float row = floor(v_uv.y * max(u_slices, 2.0));
  float torn = step(0.45, hash(vec2(row, clock)));
  float amount = hash(vec2(row + 17.0, clock * 1.7 + 3.0)) - 0.5;
  float sliceShift = amount * 0.28 * energy * torn;

  vec2 block = vec2(floor(v_uv.x * BLOCK_COLUMNS), row);
  float corrupt = step(1.0 - 0.45 * min(energy, 1.0), hash(block + clock * 7.3));
  vec2 jump =
    vec2(
      hash(block + clock * 3.1 + 5.0) - 0.5,
      hash(block + clock * 9.7 + 11.0) - 0.5
    ) *
    vec2(0.62, 0.34) *
    corrupt;

  vec2 uv = fract(v_uv + vec2(sliceShift, 0.0) + jump);
  float split = 0.02 * energy * (0.35 + abs(amount));

  vec4 color = sampleSplit(uv, split);
  color.rgb +=
    vec3(0.05, 0.015, 0.09) *
    energy *
    torn *
    hash(vec2(row, clock + 41.0)) *
    color.a;

  outColor = vec4(clamp(color.rgb, 0.0, 1.0), color.a);
}

tv-power-off.source:
#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform vec2 u_resolution;
uniform float u_aspect;
uniform float u_progress;
uniform float u_gain;
uniform float u_afterglow;
uniform vec3 u_phosphor;

in vec2 v_uv;
out vec4 outColor;

const int TAPS = 32;
const int COLUMN_TAPS = 8;
const float GOLDEN = 0.6180339887;
const float COLLAPSE_END = 0.6000;
const float PINCH_END = 0.8200;
const float MIN_SQUASH = 0.00550;
const float MIN_PINCH = 0.00400;
const float CONCENTRATION = 0.3000;
const float DECAY_CURVE = 2.6000;
const float BLACKOUT_IN = 0.0600;

void main() {
  float p = u_progress;

  if (p <= 0.0) {
    outColor = texture(u_scene, v_uv);
    return;
  }
  if (p >= 1.0) {
    outColor = vec4(0.0, 0.0, 0.0, 1.0);
    return;
  }

  float collapse = clamp(p / COLLAPSE_END, 0.0, 1.0);
  float pinch = clamp((p - COLLAPSE_END) / (PINCH_END - COLLAPSE_END), 0.0, 1.0);
  float decayed = clamp((p - PINCH_END) / (1.0 - PINCH_END), 0.0, 1.0);

  vec2 scale = vec2(pow(MIN_PINCH, pinch), pow(MIN_SQUASH, collapse));
  vec2 centered = (v_uv - 0.5) / scale + 0.5;
  vec2 span = 1.0 / (scale * u_resolution);

  vec3 sum = vec3(0.0);
  for (int i = 0; i < TAPS; i++) {
    float fi = float(i);
    vec2 at = centered + vec2(
      (fract(fi * GOLDEN + 0.5) - 0.5) * span.x,
      ((fi + 0.5) / float(TAPS) - 0.5) * span.y
    );
    vec2 inside = step(vec2(0.0), at) * step(at, vec2(1.0));
    sum += texture(u_scene, at).rgb * inside.x * inside.y;
  }

  float concentrate = pow(1.0 / (scale.x * scale.y), CONCENTRATION);
  vec3 light =
    (sum / float(TAPS)) * (1.0 + (concentrate - 1.0) * max(u_gain, 0.0));

  float glow = max(u_afterglow, 0.0);
  float bleed = smoothstep(0.2, 0.8, collapse) * (1.0 - pinch) * glow;

  if (bleed > 0.0) {
    vec3 column = vec3(0.0);
    float cx = clamp(centered.x, 0.0, 1.0);
    for (int i = 0; i < COLUMN_TAPS; i++) {
      column +=
        texture(u_scene, vec2(cx, (float(i) + 0.5) / float(COLUMN_TAPS))).rgb;
    }
    column /= float(COLUMN_TAPS);

    float dy = v_uv.y - 0.5;
    float reach = 0.02 + 0.03 * collapse;
    light +=
      column *
      mix(vec3(1.0), u_phosphor, 0.65) *
      exp(-(dy * dy) / (reach * reach)) *
      bleed *
      0.9;
  }

  if (pinch > 0.0) {
    vec2 d = (v_uv - 0.5) * vec2(u_aspect, 1.0);
    float radius = max(0.045 * glow, 0.0005);
    light +=
      u_phosphor *
      exp(-dot(d, d) / (radius * radius)) *
      smoothstep(0.0, 0.5, pinch) *
      1.15;
  }

  light *= pow(max(1.0 - decayed, 0.0001), DECAY_CURVE);

  float blackout = smoothstep(0.0, BLACKOUT_IN, p);
  outColor = vec4(
    clamp(light, 0.0, 1.0),
    mix(texture(u_scene, v_uv).a, 1.0, blackout)
  );
}

underwater-ripple.source:
#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_aspect;
uniform float u_phase;
uniform float u_amplitude;
uniform float u_scale;
uniform float u_dispersion;

in vec2 v_uv;
out vec4 outColor;

vec2 fieldGradient(vec2 p, float phase) {
  float scale = max(u_scale, 0.05);
  vec2 k1 = vec2(1.0, 0.35);
  vec2 k2 = vec2(-0.42, 1.0);
  vec2 k3 = vec2(0.78, -0.63);
  float f1 = 6.1 * scale;
  float f2 = 8.7 * scale;
  float f3 = 12.3 * scale;

  vec2 g = vec2(0.0);
  g += cos(dot(p, k1) * f1 + phase) * f1 * k1;
  g += cos(dot(p, k2) * f2 - phase * 2.0) * f2 * k2;
  g += cos(dot(p, k3) * f3 + phase * 3.0) * f3 * k3;

  return g / (3.0 * f2);
}

void main() {
  vec2 p = vec2(v_uv.x * u_aspect, v_uv.y);
  vec2 grad = fieldGradient(p, u_phase);

  vec2 offset = grad * u_amplitude;
  float strength = length(grad);
  vec2 direction = strength > 0.0001 ? grad / strength : vec2(0.0);
  float spread = u_dispersion * u_amplitude * 0.3 * min(strength, 2.0);

  vec2 base = v_uv + vec2(offset.x / u_aspect, offset.y);
  vec2 lead = vec2(direction.x / u_aspect, direction.y) * spread;

  vec4 center = texture(u_scene, base);
  float r = texture(u_scene, base + lead).r;
  float b = texture(u_scene, base - lead).b;

  outColor = vec4(r, center.g, b, center.a);
}

vhs-filter.source:
#version 300 es
precision highp float;

uniform sampler2D u_scene;
uniform float u_frame;
uniform float u_time;
uniform float u_bleed;
uniform float u_wobble;
uniform float u_noise;
uniform float u_intensity;

in vec2 v_uv;
out vec4 outColor;

const float PI = 3.141592653589793;
const float LINES = 486.0;
const int TAPS = 6;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float valueNoise(float x) {
  float i = floor(x);
  float f = fract(x);
  float a = hash(vec2(i, 7.0));
  float b = hash(vec2(i + 1.0, 7.0));
  return mix(a, b, f * f * (3.0 - 2.0 * f));
}

vec3 rgb2yiq(vec3 c) {
  return vec3(
    dot(c, vec3(0.299, 0.587, 0.114)),
    dot(c, vec3(0.5959, -0.2746, -0.3213)),
    dot(c, vec3(0.2115, -0.5227, 0.3112))
  );
}

vec3 yiq2rgb(vec3 c) {
  return vec3(
    c.x + 0.956 * c.y + 0.619 * c.z,
    c.x - 0.272 * c.y - 0.647 * c.z,
    c.x - 1.106 * c.y + 1.703 * c.z
  );
}

void main() {
  float line = floor(v_uv.y * LINES);
  float clock = mod(u_frame, 64.0);

  float drift =
    sin(v_uv.y * 37.0 + u_time * 2.3) * 0.55 +
    sin(v_uv.y * 96.0 - u_time * 1.1) * 0.25;
  float jitter = valueNoise(line * 0.61 + u_time * 24.0) - 0.5;
  float wobble = (drift * 0.35 + jitter * 0.9) * 0.007 * u_wobble * u_intensity;

  float band = smoothstep(0.955, 0.994, v_uv.y);
  float tear = valueNoise(line * 2.7 + u_time * 43.0) - 0.5;
  float headSwitch = band * tear * 0.085 * u_intensity;

  vec2 uv = vec2(v_uv.x + wobble + headSwitch, v_uv.y);
  vec4 base = texture(u_scene, uv);
  float luma = rgb2yiq(base.rgb).x;

  float smear = u_bleed * 0.02 * u_intensity;
  vec2 chroma = vec2(0.0);
  float total = 0.0;
  for (int i = 0; i < TAPS; i++) {
    float t = float(i) / float(TAPS - 1);
    float weight = 1.0 - t * 0.72;
    vec3 tap = texture(u_scene, vec2(uv.x - smear * t, uv.y)).rgb;
    chroma += rgb2yiq(tap).yz * weight;
    total += weight;
  }

  vec3 color = yiq2rgb(vec3(luma, chroma / total));

  float scan = 0.94 + 0.06 * cos(v_uv.y * LINES * PI);
  color *= mix(1.0, scan, u_intensity);

  float grain =
    hash(vec2(v_uv.x * 640.0 + clock * 13.0, line + clock * 5.0)) - 0.5;
  color += grain * 0.07 * u_noise * u_intensity;

  color = mix(color, vec3(luma), band * 0.55 * u_intensity);
  color += band * (hash(vec2(line, clock * 3.0)) - 0.5) * 0.26 * u_intensity;

  outColor = vec4(clamp(color, 0.0, 1.0), base.a);
}

rush-type.source:
precision highp float;
varying vec2 vUv;

uniform sampler2D uText;
uniform vec2 uRes;
uniform vec2 uHalfPx;
uniform float uAtlasRows;
uniform float uSx;
uniform vec3 uSyQ;
uniform float uCenterY;
uniform float uSwapU;
uniform float uHalfA;
uniform float uHalfB;
uniform vec3 uK;
uniform vec2 uSwapScl;
uniform float uShape;
uniform float uRoll;
uniform float uLag;
uniform float uThin;
uniform float uBloom;
uniform float uGain;
uniform float uExp;
uniform float uFocal;
uniform vec3 uPos;
uniform vec4 uRot;
uniform float uCrt;
uniform float uTime;
uniform vec4 uGlow;
uniform float uGlowAmp;
uniform vec3 uColor;
uniform vec3 uBg;

#define SAMPLES 28
#define BLOOM_TAPS 4
#define BLOOM_SPREAD 3.200
#define BLOOM_BIAS 3.500
#define TAU 6.2831853
#define CRT_PITCH 5.000
#define CRT_MASK 0.1600
#define CRT_SCAN_PITCH 3.000
#define CRT_SCAN 0.1200
#define CRT_BEAM 0.7000
#define CRT_HUM 0.0350
#define CRT_HUM_SPEED 0.1400

vec2 atlasUv(float sy, float halfIdx, vec2 wordPoint, out float inside) {
  float sx = max(uSx, 1e-4);
  float sv = max(abs(sy), 1e-4);
  vec2 q = vec2(
    (wordPoint.x / sx + uHalfPx.x * 0.5) / uHalfPx.x,
    (wordPoint.y / sv + uHalfPx.y * 0.5) / uHalfPx.y
  );
  inside = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
  return vec2(
    clamp(q.x, 0.0, 1.0),
    (clamp(q.y, 0.0, 1.0) + halfIdx) / uAtlasRows
  );
}

float tap(float sy, float halfIdx, vec2 wordPoint, float front) {
  float inside;
  vec2 texturePoint = atlasUv(sy, halfIdx, wordPoint, inside);
  float value = texture2D(uText, texturePoint).r * inside * front;
  return value * mix(1.0, value, uThin);
}

float tapBlur(float sy, float halfIdx, vec2 wordPoint, float front) {
  float inside;
  vec2 texturePoint = atlasUv(sy, halfIdx, wordPoint, inside);
  return texture2D(uText, texturePoint, BLOOM_BIAS).r * inside * front;
}

void main() {
  vec2 pixel = vUv * uRes;
  vec2 center = vec2(uRes.x * 0.5, uRes.y * uCenterY);
  vec2 screenPoint = pixel - center;

  float sinYaw = uRot.x;
  float cosYaw = uRot.y;
  float sinPitch = uRot.z;
  float cosPitch = uRot.w;
  float a1 = -(screenPoint.x * sinYaw + uFocal * cosYaw);
  float b1 = sinPitch * (screenPoint.x * cosYaw - uFocal * sinYaw);
  float c1 = uFocal * uPos.x - screenPoint.x * uPos.z;
  float a2 = -screenPoint.y * sinYaw;
  float b2 = screenPoint.y * sinPitch * cosYaw - uFocal * cosPitch;
  float c2 = uFocal * uPos.y - screenPoint.y * uPos.z;
  float determinant = a1 * b2 - a2 * b1;
  float inverse = 1.0 / (abs(determinant) < 1e-4 ? 1e-4 : determinant);
  float a = (c1 * b2 - c2 * b1) * inverse;
  float b = (a1 * c2 - a2 * c1) * inverse;
  float cameraZ = uPos.z - a * sinYaw + b * sinPitch * cosYaw;
  vec2 wordPoint = vec2(a, b);
  float front = step(uFocal * 0.05, cameraZ);
  vec3 accumulated = vec3(0.0);

  if (abs(uSyQ.y) + abs(uSyQ.z) < 1e-5) {
    accumulated = vec3(tap(uSyQ.x, uHalfA, wordPoint, front));
  } else {
    float offset =
      uLag * (wordPoint.x / uRes.x) - uRoll * (screenPoint.y / uRes.y);
    float weightSum = 0.0;

    for (int i = 0; i < SAMPLES; i++) {
      float u = float(i) / float(SAMPLES - 1) - 0.5;
      float weight = 1.0 - uShape * abs(u) * 2.0;
      weightSum += weight;
      float shiftedU = u + offset;
      vec3 shutterU = shiftedU * uK;
      vec3 sy = uSyQ.x + uSyQ.y * shutterU + uSyQ.z * shutterU * shutterU;
      accumulated.r += weight * tap(
        sy.r * (shutterU.r < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.r < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      accumulated.g += weight * tap(
        sy.g * (shutterU.g < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.g < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      accumulated.b += weight * tap(
        sy.b * (shutterU.b < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.b < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
    }

    accumulated /= max(weightSum, 1e-4);

    vec3 halo = vec3(0.0);
    for (int j = 0; j < BLOOM_TAPS; j++) {
      float u =
        (float(j) / float(BLOOM_TAPS - 1) - 0.5) * BLOOM_SPREAD + offset;
      vec3 shutterU = u * uK;
      vec3 sy = uSyQ.x + uSyQ.y * shutterU + uSyQ.z * shutterU * shutterU;
      halo.r += tapBlur(
        sy.r * (shutterU.r < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.r < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      halo.g += tapBlur(
        sy.g * (shutterU.g < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.g < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
      halo.b += tapBlur(
        sy.b * (shutterU.b < uSwapU ? uSwapScl.x : uSwapScl.y),
        shutterU.b < uSwapU ? uHalfA : uHalfB,
        wordPoint,
        front
      );
    }
    accumulated += halo * (uBloom / float(BLOOM_TAPS));
    accumulated *= uGain;
  }

  accumulated =
    (1.0 - exp(-accumulated * uExp)) / (1.0 - exp(-uExp));

  vec2 glowDistance =
    (pixel - uGlow.xy) / max(uGlow.zw, vec2(1.0));
  float ground =
    uGlowAmp * (1.0 - smoothstep(0.0, 1.0, length(glowDistance)));
  accumulated += ground * (1.0 - accumulated);

  if (uCrt > 0.0) {
    float luminance = max(max(accumulated.r, accumulated.g), accumulated.b);
    vec3 maskWave = 0.5 + 0.5 * cos(
      TAU * (pixel.x / CRT_PITCH - vec3(0.0, 0.33333, 0.66667))
    );
    vec3 mask = mix(vec3(1.0), maskWave * 2.0, CRT_MASK * uCrt);
    float scanWave = 0.5 + 0.5 * cos(TAU * pixel.y / CRT_SCAN_PITCH);
    float scan =
      1.0 - CRT_SCAN * uCrt * (1.0 - CRT_BEAM * luminance) * (1.0 - scanWave);
    float bar = 0.5 + 0.5 * cos(
      TAU * (pixel.y / uRes.y - uTime * CRT_HUM_SPEED)
    );
    float hum = 1.0 + CRT_HUM * uCrt * (bar * 2.0 - 1.0);
    accumulated *= mask * scan * hum;
  }

  gl_FragColor = vec4(uBg + (uColor - uBg) * accumulated, 1.0);
}
